public class TimeValidatorTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    public static void main(String[] args) {
        check("isValidTime(\"07:30\")", true, TimeValidator.isValidTime("07:30"));
        check("isValidTime(\"23:59\")", true, TimeValidator.isValidTime("23:59"));
        check("isValidTime(\"00:00\")", true, TimeValidator.isValidTime("00:00"));
        check("isValidTime(\"19:05\")", true, TimeValidator.isValidTime("19:05"));
        check("isValidTime(\"7:30\") needs two hour digits", false, TimeValidator.isValidTime("7:30"));
        check("isValidTime(\"24:00\") hour too large", false, TimeValidator.isValidTime("24:00"));
        check("isValidTime(\"12:60\") minute too large", false, TimeValidator.isValidTime("12:60"));
        check("isValidTime(\"1230\") missing colon", false, TimeValidator.isValidTime("1230"));
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

